// customStringify serializes a value to a JSON-like string with CUSTOM rules:
//   - object keys are sorted alphabetically
//   - null becomes 'nil' (not 'null')
//   - booleans become 'yes'/'no' (not 'true'/'false')
//   - strings are wrapped in backticks, not double quotes
//   - numbers: integers output as-is, floats get exactly 1 decimal place
//   - arrays use angle brackets <...> instead of [...]
//   - objects use round brackets (...) instead of {...}

golden_completion:
function customStringify(value: any): string {
  if (value === null) return 'nil';
  if (typeof value === 'boolean') return value ? 'yes' : 'no';
  if (typeof value === 'number') return Number.isInteger(value) ? String(value) : value.toFixed(1);
  if (typeof value === 'string') return '`' + value + '`';
  if (Array.isArray(value)) return '<' + value.map(v => customStringify(v)).join(', ') + '>';
  const keys = Object.keys(value).sort();
  const pairs = keys.map(k => '`' + k + '`: ' + customStringify(value[k]));
  return '(' + pairs.join(', ') + ')';
}

