      case 'pp': return date.getHours() >= 12 ? 'pm' : 'am';
      case 'WW': return ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'][date.getDay()];
      default: return match;
    }
  });
}

