function base52Encode(data: string | Buffer, alphabet: string = REVERSED_B52, pad: string = '.'): string {
  const buf: Buffer = Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf-8');
  if (buf.length === 0) return '';
  const base: bigint = BigInt(alphabet.length);
  const digits: string[] = [];
  let n: bigint = bytesToBigInt(buf);
  while (n > 0n) { digits.push(alphabet[Number(n % base)]); n = n / base; }
  const raw: string = digits.reverse().join('');
  const targetLen: number = Math.ceil(buf.length * 8 / Math.log2(52));
  return raw.padStart(targetLen, pad);
}

