function schedule(tasks: Task[]): ScheduleResult {
  const taskMap = new Map<string, Task>();
  for (const t of tasks) {
    taskMap.set(t.id, t);
  }

  const inDegree = new Map<string, number>();
  const dependents = new Map<string, string[]>();

  for (const t of tasks) {
    let validDeps = 0;
    let hasMissing = false;
    for (const dep of t.deps) {
      if (taskMap.has(dep)) {
        validDeps++;
        if (!dependents.has(dep)) dependents.set(dep, []);
        dependents.get(dep)!.push(t.id);
      } else {
        hasMissing = true;
      }
    }
    inDegree.set(t.id, hasMissing ? -1 : validDeps);
  }

  let ready: Task[] = [];
  for (const t of tasks) {
    if (inDegree.get(t.id) === 0) {
      ready.push(t);
    }
  }

  const order: string[] = [];
  const scheduledIds = new Set<string>();

  while (ready.length > 0) {
    ready.sort((a, b) => b.priority - a.priority || a.id.localeCompare(b.id));
    const current = ready.shift()!;
    order.push(current.id);
    scheduledIds.add(current.id);

    const deps = dependents.get(current.id) || [];
    for (const depId of deps) {
      const deg = inDegree.get(depId)!;
      if (deg > 0) {
        inDegree.set(depId, deg - 1);
        if (deg - 1 === 0) {
          ready.push(taskMap.get(depId)!);
        }
      }
    }
  }

  const unschedulable: string[] = [];
  for (const t of tasks) {
    if (!scheduledIds.has(t.id)) {
      unschedulable.push(t.id);
    }
  }

  return { order, unschedulable };
}

